JOIN app.universities u ON u.code = v.code
ON CONFLICT (university_id, study_level) DO UPDATE SET
  study_level = EXCLUDED.study_level,
  majors = EXCLUDED.majors,
  stem_majors = EXCLUDED.stem_majors,
  academic_year = EXCLUDED.academic_year,
  tuition_usd = EXCLUDED.tuition_usd,
  living_usd = EXCLUDED.living_usd,
  fees_usd = EXCLUDED.fees_usd,
  min_gpa4 = EXCLUDED.min_gpa4,
  min_ielts = EXCLUDED.min_ielts,
  min_toefl = EXCLUDED.min_toefl,
  min_duolingo = EXCLUDED.min_duolingo,
  avg_gpa4 = EXCLUDED.avg_gpa4,
  sat25 = EXCLUDED.sat25,
  sat75 = EXCLUDED.sat75,
  sat_policy = EXCLUDED.sat_policy,
  deadlines_json = EXCLUDED.deadlines_json,
  notes = EXCLUDED.notes,
  source_url = EXCLUDED.source_url,
  retrieved_at = EXCLUDED.retrieved_at,
  updated_at = now();

INSERT INTO app.university_offerings (id, university_id, study_level, majors, stem_majors, academic_year, tuition_usd, living_usd, fees_usd, min_gpa4, min_ielts, min_toefl, min_duolingo, avg_gpa4, sat25, sat75, sat_policy, deadlines_json, notes, source_url, retrieved_at, created_at)
SELECT gen_random_uuid(), u.id,
  v.study_level::text,
  v.majors::text[],
  v.stem_majors::text[],
  v.academic_year::text,
  v.tuition_usd::numeric,
  v.living_usd::numeric,
  v.fees_usd::numeric,
  v.min_gpa4::numeric,
  v.min_ielts::numeric,
  v.min_toefl::numeric,
  v.min_duolingo::numeric,
  v.avg_gpa4::numeric,
  v.sat25::integer,
  v.sat75::integer,
  v.sat_policy::text,
  v.deadlines_json::jsonb,
  v.notes::text,
  v.source_url::text,
  v.retrieved_at::date,
